    <title>Mailing List</title>
    <link rel="stylesheet" href="style.css" />
  </head>
  <body>
    <main>
      <h1>Mailing List</h1>
      <p>This dialog is scaffolded for Phase 3 implementation.</p>
      <section>
        <label for="listName">Mailing List Name</label>
        <input id="listName" type="text" />
      </section>
      <section id="recipientContainer" aria-live="polite"></section>
